contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(uint v) public payable {
        // require we have no preconditions on msg.value; ensure v is not larger than current balance to avoid revert from insufficient funds
        require(v <= address(c).balance);

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;

        bool didRevert;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(c).balance;

        // General rule: if caller (this contract) is owner, withdraw(v) with v <= balance should not increase balance and should not change owner.
        // We assert that either the call reverted (then state may be unchanged) or it succeeded and owner unchanged and balanceAfter <= balanceBefore.
        assert(didRevert || (ownerBefore == ownerAfter && balanceAfter <= balanceBefore));
    }

    receive() external payable { }
}

