pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v) internal {
        vm.assume(v <= address(c).balance);
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        uint balanceBefore = address(c).balance;
        bool didRevert;
        try c.withdraw(v) {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        address ownerAfter;
        try c.owner() returns (address __r) { ownerAfter = __r; } catch { return; }
        uint balanceAfter = address(c).balance;
        assertTrue(didRevert || (ownerBefore == ownerAfter && balanceAfter <= balanceBefore));
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable { }
}
